sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var patEmail = current.patient ? current.patient.email.toString() : '';
    var patName = current.patient ? current.patient.name.toString() : '';
    var docEmail = '';
    if (current.doctor) {
        var dGr = current.doctor.getRefRecord();
        docEmail = dGr.getValue('email') || (dGr.user && dGr.user.email ? dGr.user.email.toString() : '');
    }

    // 1. Appointment moves to Confirmed ('3')
    if (current.status == '3' && previous.status != '3') {
        // Patient notification
        gs.eventQueue('x_2223823_apollo_0.appointment_confirmed', current, patEmail, patName);

        // Doctor notification
        gs.eventQueue('x_2223823_apollo_0.doctor_new_appointment', current, docEmail, '');
    }

    // 2. Appointment moves to Cancelled ('7')
    if (current.status == '7' && previous.status != '7') {
        // Patient notification
        gs.eventQueue('x_2223823_apollo_0.appointment_cancelled', current, patEmail, patName);

        // Doctor notification
        gs.eventQueue('x_2223823_apollo_0.doctor_appointment_cancelled', current, docEmail, '');
    }

    // 3. Payment Link Generated (slot hold initiated)
    if (!current.hold_expires_at.nil() && (current.hold_expires_at.changes() || current.operation() == 'insert')) {
        gs.eventQueue('x_2223823_apollo_0.payment_link', current, patEmail, patName);
    }
})(current, previous);
